def merge_sort(arr, key=lambda x: x):
    if len(arr) <= 1: return arr
    mid = len(arr)//2
    return merge(merge_sort(arr[:mid], key), merge_sort(arr[mid:], key), key)
def merge(left, right, key=lambda x: x):
    r = []; i = j = 0
    while i < len(left) and j < len(right):
        if key(left[i]) <= key(right[j]): r.append(left[i]); i += 1
        else: r.append(right[j]); j += 1
    r.extend(left[i:]); r.extend(right[j:])
    return r
